import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static class Matrix extends ArrayList<ArrayList<Integer>> {
        public Matrix(int rows, int cols) {
            super();
            for (int i = 0; i < rows; i++) {
                ArrayList<Integer> row = new ArrayList<>();
                for (int j = 0; j < cols; j++) {
                    row.add(0);
                }
                this.add(row);
            }
        }

        public static Matrix identity(int size) {
            Matrix id = new Matrix(size, size);
            for (int i = 0; i < size; i++) {
                id.get(i).set(i, 1);
            }
            return id;
        }

        public Matrix multiply(Matrix b) {
            int n = this.size();
            int k = this.get(0).size();
            int m = b.get(0).size();
            Matrix res = new Matrix(n, m);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    long sum = 0;
                    for (int l = 0; l < k; l++) {
                        sum += (long) this.get(i).get(l) * b.get(l).get(j);
                    }
                    res.get(i).set(j, (int) (sum % MOD));
                }
            }
            return res;
        }
    }

    static Matrix shift(Matrix a, int shift) {
        int size = a.size() - 1;
        shift = (size - shift) % size;
        Matrix res = new Matrix(a.size(), a.get(0).size());
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                res.get(i).set(j, a.get((i + shift) % size).get((j + shift) % size));
            }
        }
        for (int j = 0; j < size; j++) {
            res.get(size).set(j, a.get(size).get((j + shift) % size));
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        int max_depth = 0;
        long tmpN = n;
        while (tmpN != 0) {
            max_depth++;
            tmpN /= k;
        }

        List<Matrix> dp = new ArrayList<>();
        // Initialize dp[0]
        Matrix dp0 = new Matrix(k + 1, k + 1);
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= k; j++) {
                if (i == j || j == 0) {
                    dp0.get(i).set(j, 1);
                } else {
                    dp0.get(i).set(j, 0);
                }
            }
        }
        dp.add(dp0);

        // Build identity matrix
        Matrix identity = Matrix.identity(k + 1);

        for (int depth = 1; depth < max_depth; depth++) {
            Matrix prev = dp.get(depth - 1);
            Matrix current = new Matrix(k + 1, k + 1);
            for (int i = 0; i <= k; i++) {
                current.get(i).set(i, 1);
            }
            int curx = k;
            int i = 0;
            while ((1 << i) <= curx) {
                if ((curx & (1 << i)) != 0) {
                    current = prev.multiply(shift(current, 1 << i));
                    curx ^= (1 << i);
                }
                prev = prev.multiply(shift(prev, 1 << i));
                i++;
            }
            dp.add(current);
        }

        // Initialize base matrix
        Matrix base = new Matrix(1, k + 1);
        base.get(0).set(k, 1);

        long x = n;
        List<Integer> digits = new ArrayList<>();
        while (x != 0) {
            digits.add((int) (x % k));
            x /= k;
        }

        int shift_counter = 0;
        for (int idx = digits.size() - 1; idx >= 0; idx--) {
            int rest = digits.get(idx);
            for (int it = 0; it < rest; it++, shift_counter = (shift_counter + 1) % k) {
                base = base.multiply(shift(dp.get(idx), shift_counter));
            }
        }

        int result = 0;
        for (int i = 0; i <= k; i++) {
            result = (result + base.get(0).get(i)) % (int) MOD;
        }

        System.out.println(result);
        sc.close();
    }
}
